# Task-level accuracy evaluation for Goal Accessibility Preservation.
# Measures whether models can correctly answer questions at the end of multi-turn conversations.

import argparse
import json
import re
import os
import math
from pathlib import Path
from collections import defaultdict

import torch
from transformers import AutoTokenizer, AutoModelForCausalLM


def load_model(model_path, adapter_path=None, gpu=0):
    device = f"cuda:{gpu}" if torch.cuda.is_available() else "cpu"
    tokenizer = AutoTokenizer.from_pretrained(model_path, trust_remote_code=True)
    model = AutoModelForCausalLM.from_pretrained(
        model_path,
        torch_dtype=torch.bfloat16,
        device_map=device,
        trust_remote_code=True,
    )

    if adapter_path:
        from peft import PeftModel
        model = PeftModel.from_pretrained(model, adapter_path)
        model = model.merge_and_unload()

    model.eval()
    if tokenizer.pad_token is None:
        tokenizer.pad_token = tokenizer.eos_token
    return model, tokenizer, device


def build_prompt(tokenizer, conversation):
    if hasattr(tokenizer, "apply_chat_template"):
        try:
            prompt = tokenizer.apply_chat_template(
                conversation, tokenize=False, add_generation_prompt=True
            )
            return prompt
        except Exception:
            pass

    parts = []
    for turn in conversation:
        role = turn["role"]
        content = turn["content"]
        if role == "user":
            parts.append(f"User: {content}")
        else:
            parts.append(f"Assistant: {content}")
    parts.append("Assistant:")
    return "\n".join(parts)


def generate_answer(model, tokenizer, device, conversation, max_new_tokens=256):
    prompt = build_prompt(tokenizer, conversation)
    inputs = tokenizer(prompt, return_tensors="pt", truncation=True, max_length=8192)
    inputs = {k: v.to(device) for k, v in inputs.items()}

    with torch.no_grad():
        outputs = model.generate(
            **inputs,
            max_new_tokens=max_new_tokens,
            do_sample=False,
            temperature=None,
            top_p=None,
            pad_token_id=tokenizer.pad_token_id,
        )

    new_tokens = outputs[0][inputs["input_ids"].shape[1]:]
    return tokenizer.decode(new_tokens, skip_special_tokens=True).strip()


def normalize_text(text):
    text = text.lower().strip()
    text = re.sub(r"\s+", " ", text)
    text = re.sub(r"[,\.\!\?\;:]+$", "", text)
    return text


def extract_number(text):
    matches = re.findall(r"-?\d+(?:\.\d+)?", text)
    if matches:
        return float(matches[-1])
    return None


def score_extraction(generated, expected):
    gen_norm = normalize_text(generated)
    exp_norm = normalize_text(expected)

    if exp_norm in gen_norm:
        return True

    fields = re.split(r"[,;\n]", expected)
    if len(fields) > 1:
        matched = 0
        for field in fields:
            kv = field.strip()
            if not kv:
                continue
            if normalize_text(kv) in gen_norm:
                matched += 1
            else:
                parts = re.split(r"[:=]", kv, maxsplit=1)
                if len(parts) == 2:
                    val = normalize_text(parts[1])
                    if val and val in gen_norm:
                        matched += 1
        total_fields = sum(1 for f in fields if f.strip())
        if total_fields > 0 and matched / total_fields >= 0.8:
            return True

    return False


def score_reasoning(generated, expected):
    gen_norm = normalize_text(generated)
    exp_norm = normalize_text(expected)

    if exp_norm in gen_norm:
        return True

    exp_num = extract_number(expected)
    if exp_num is not None:
        gen_num = extract_number(generated)
        if gen_num is not None:
            if exp_num == 0 and gen_num == 0:
                return True
            if math.isclose(exp_num, gen_num, rel_tol=1e-3, abs_tol=1e-2):
                return True

    exp_words = set(exp_norm.split())
    gen_words = set(gen_norm.split())
    if exp_words and exp_words.issubset(gen_words):
        return True

    return False


def score_sample(generated, expected, task_type):
    if task_type == "extraction":
        return score_extraction(generated, expected)
    return score_reasoning(generated, expected)


def evaluate(model_path, adapter_path, data_path, output_dir,
             gpu=0, max_samples=None, max_new_tokens=256):
    with open(data_path) as f:
        samples = json.load(f)

    samples = [s for s in samples if s.get("expected_answer") is not None]
    if max_samples:
        samples = samples[:max_samples]

    if not samples:
        print("No samples with expected_answer found.")
        return None

    print(f"Loaded {len(samples)} samples with expected answers")
    model, tokenizer, device = load_model(model_path, adapter_path, gpu)
    print(f"Model loaded on {device}")

    results_samples = []
    correct_by_type = defaultdict(lambda: {"correct": 0, "total": 0})
    correct_by_depth = defaultdict(lambda: {"correct": 0, "total": 0})
    total_correct = 0

    for i, sample in enumerate(samples):
        generated = generate_answer(
            model, tokenizer, device, sample["conversation"], max_new_tokens
        )
        is_correct = score_sample(generated, sample["expected_answer"], sample["task_type"])
        total_correct += int(is_correct)

        task_type = sample["task_type"]
        correct_by_type[task_type]["total"] += 1
        correct_by_type[task_type]["correct"] += int(is_correct)

        depth = sample["turn_depth"]
        correct_by_depth[depth]["total"] += 1
        correct_by_depth[depth]["correct"] += int(is_correct)

        results_samples.append({
            "id": sample["id"],
            "task_type": task_type,
            "turn_depth": depth,
            "expected": sample["expected_answer"],
            "generated": generated,
            "correct": is_correct,
        })

        if (i + 1) % 10 == 0:
            print(f"  [{i+1}/{len(samples)}] running accuracy: {total_correct/(i+1):.3f}")

    by_task_type = {}
    for tt, counts in correct_by_type.items():
        n = counts["total"]
        c = counts["correct"]
        by_task_type[tt] = {"accuracy": c / n if n else 0.0, "n_samples": n, "n_correct": c}

    by_turn_depth = {}
    for d in sorted(correct_by_depth.keys()):
        counts = correct_by_depth[d]
        n = counts["total"]
        c = counts["correct"]
        by_turn_depth[str(d)] = {"accuracy": c / n if n else 0.0, "n": n}

    model_name = Path(model_path).name
    output = {
        "model": model_name,
        "adapter": adapter_path,
        "results": {
            "overall_accuracy": total_correct / len(samples) if samples else 0.0,
            "by_task_type": by_task_type,
            "by_turn_depth": by_turn_depth,
        },
        "samples": results_samples,
    }

    os.makedirs(output_dir, exist_ok=True)
    suffix = f"_{Path(adapter_path).name}" if adapter_path else ""
    out_path = Path(output_dir) / f"task_accuracy_{model_name}{suffix}.json"
    with open(out_path, "w") as f:
        json.dump(output, f, indent=2, ensure_ascii=False)

    print(f"\nResults saved to {out_path}")
    print(f"Overall accuracy: {output['results']['overall_accuracy']:.3f}")
    for tt, info in by_task_type.items():
        print(f"  {tt}: {info['accuracy']:.3f} ({info['n_correct']}/{info['n_samples']})")
    for d, info in by_turn_depth.items():
        print(f"  depth {d}: {info['accuracy']:.3f} (n={info['n']})")

    return output


if __name__ == "__main__":
    parser = argparse.ArgumentParser(description="Task-level accuracy evaluation")
    parser.add_argument("--model_path", default="/root/autodl-tmp/models/Qwen3-8B")
    parser.add_argument("--adapter_path", default=None)
    parser.add_argument("--data_path", required=True)
    parser.add_argument("--output_dir", default="./eval_results")
    parser.add_argument("--gpu", type=int, default=0)
    parser.add_argument("--max_samples", type=int, default=None)
    parser.add_argument("--max_new_tokens", type=int, default=256)
    args = parser.parse_args()

    evaluate(
        model_path=args.model_path,
        adapter_path=args.adapter_path,
        data_path=args.data_path,
        output_dir=args.output_dir,
        gpu=args.gpu,
        max_samples=args.max_samples,
        max_new_tokens=args.max_new_tokens,
    )
